mapper.select:
SELECT e.*
FROM interpretation_embedding e
         JOIN interpretation_session s ON e.session_id = s.session_id
WHERE s.user_id = #{userId}
  AND COALESCE(s.deleted, 0) = 0

      AND e.meeting_id = #{filterMeetingId}


      AND e.speaker_name LIKE CONCAT('%', #{filterSpeakerName}, '%')


      AND s.start_time >= #{filterSince}

ORDER BY e.id DESC
LIMIT 2000
